<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Copy, RefreshCw, Save } from 'lucide-vue-next'
const props=defineProps<{csrf:string}>(),emit=defineEmits<{saved:[data:Record<string,any>]}>()
const stats=ref<any>(null),protocol=ref<any[]>([]),config=ref<Record<string,any>|null>(null),logs=ref<any[]>([]),error=ref(''),notice=ref(''),token=ref(''),busy=ref(false)
async function api(path:string,options:RequestInit={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrf,...options.headers}});if(!response.ok){const data=await response.json();throw new Error(typeof data.detail==='string'?data.detail:'请求失败')}return response.json()}
async function load(){try{[config.value,logs.value,stats.value,protocol.value]=await Promise.all([api('/api/settings'),api('/api/upload-logs'),api('/api/storage'),api('/api/protocol-logs')]);if(config.value){for(const source of stats.value.devices){if(!config.value.device_profiles.some((p:any)=>p.source===source))config.value.device_profiles.push({source,label:'',location:''})}}}catch(e){error.value=(e as Error).message}}
onMounted(load)
const formatBytes=(n:number)=>{const units=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<4){n/=1024;i++}return n.toFixed(i?1:0)+' '+units[i]}
function addDevice(){config.value?.device_profiles.push({source:'',label:'',location:''})}
async function save(){if(!config.value)return;if((config.value.file_retention_days||config.value.trash_retention_days)&&!confirm('保存后将自动执行保留策略：过期原件移入回收站，过期回收站文件永久删除。确认启用？'))return;busy.value=true;error.value='';try{await api('/api/settings',{method:'PUT',body:JSON.stringify(config.value)});notice.value='系统设置已保存';emit('saved',config.value)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function resetToken(){if(!confirm('生成新上传令牌后，旧令牌立即失效，需要重新配置扫描仪。继续？'))return;busy.value=true;error.value='';try{token.value=(await api('/api/settings/upload-token',{method:'POST'})).token;if(config.value)config.value.upload_token_configured=true;notice.value='新令牌仅显示这一次，请复制到扫描仪配置中'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function copy(value:string){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(value);else{const el=document.createElement('textarea');el.value=value;document.body.appendChild(el);el.select();if(!document.execCommand('copy'))throw Error();el.remove()}notice.value='已复制'}catch{error.value='无法自动复制，请选择文本手动复制'}}
async function cleanup(){if(!confirm('立即按已保存的保留策略运行清理？过期回收站文件无法恢复。'))return;busy.value=true;try{const data=await api('/api/maintenance/run',{method:'POST'});notice.value=`已移入回收站 ${data.moved_to_trash} 个，永久删除 ${data.purged} 个，待重试 ${data.pending} 个`;stats.value=await api('/api/storage')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="system-settings"><p v-if="error" class="banner error" role="alert">{{error}}</p><p v-if="notice" class="banner success" role="status">{{notice}}</p><template v-if="config"><section class="settings-section"><h2>扫描仪接入</h2><p>只显示 ScanHub 服务和最近上传记录，不推测扫描仪是否在线。</p><p v-if="logs.length">最近上传：{{new Date(logs[0].received_at*1000).toLocaleString('zh-CN')}} · {{logs[0].status>=200&&logs[0].status<300?'成功':'失败'}}（{{logs[0].status}}）</p><label>HTTP 上传地址<div class="copy-row"><input readonly :value="config.upload_url"><button aria-label="复制上传地址" @click="copy(config.upload_url)"><Copy :size="17"/></button></div></label><div class="token-row"><span>上传令牌：{{config.upload_token_configured?'已配置':'未配置'}}</span><button :disabled="busy" @click="resetToken"><RefreshCw :size="16"/>生成 / 重置令牌</button></div><label v-if="token">新上传令牌（仅显示一次）<div class="copy-row"><input readonly :value="token"><button aria-label="复制新令牌" @click="copy(token)"><Copy :size="17"/></button></div></label><p>扫描仪采用 multipart 文件字段 paper，二维码字段 text，可添加 device 和 batch_id。设备实际协议仍待实测，先用调试接收器验证。</p><label class="inline"><input v-model="config.debug_enabled" type="checkbox">启用 HTTP 协议调试（默认关闭）</label><p>调试地址为 /api/debug/upload；须预先配置独立 ADMIN_TOKEN。未知原始请求体可能包含敏感信息。</p></section><section class="settings-section"><h2>文件管理</h2><div class="settings-fields"><label>默认排序<select v-model="config.default_sort"><option value="newest">最新上传</option><option value="oldest">最早上传</option><option value="name">文件名称</option><option value="size">文件大小</option></select></label><label>默认视图<select v-model="config.default_view"><option value="grid">网格</option><option value="list">列表</option></select></label><label>缩略图大小<input v-model.number="config.thumbnail_size" type="number" min="150" max="300"></label><label>推断批次间隔（秒）<input v-model.number="config.batch_interval" type="number" min="1" max="3600"></label><label>最大请求大小（MiB）<input v-model.number="config.max_upload_mb" type="number" min="1" max="1024"></label></div></section><section class="settings-section"><div class="section-heading"><h2>设备来源管理</h2><button @click="addDevice">添加来源</button></div><p>来源标识对应上传参数 device。别名和位置不会修改历史原件或批次身份。</p><div v-for="(profile,index) in config.device_profiles" :key="index" class="device-profile"><label>来源标识<input v-model="profile.source" maxlength="200"></label><label>显示名称<input v-model="profile.label" maxlength="100"></label><label>所在位置<input v-model="profile.location" maxlength="200"></label><button @click="config.device_profiles.splice(index,1)">移除配置</button></div></section><section class="settings-section"><h2>保留策略</h2><p>0 表示永久保留。原件过期后先移入回收站；回收站保留期从移入时间起算。每 5 分钟检查一次。</p><div class="settings-fields"><label>原件保留天数<input v-model.number="config.file_retention_days" type="number" min="0" max="36500" list="retention-days"></label><label>回收站保留天数<input v-model.number="config.trash_retention_days" type="number" min="0" max="36500" list="retention-days"></label><datalist id="retention-days"><option v-for="day in [0,1,3,7,30]" :key="day" :value="day"/></datalist></div><button :disabled="busy" @click="cleanup">按已保存策略立即清理</button></section><section v-if="stats" class="settings-section"><h2>存储信息</h2><dl class="storage-summary"><div><dt>文件总数</dt><dd>{{stats.count}}</dd></div><div><dt>原件总占用（含回收站）</dt><dd>{{formatBytes(stats.bytes)}}</dd></div><div><dt>回收站占用</dt><dd>{{formatBytes(stats.trash_bytes)}}</dd></div><div><dt>磁盘剩余</dt><dd>{{formatBytes(stats.free_bytes)}}</dd></div></dl></section><div class="settings-save"><button class="primary" :disabled="busy" @click="save"><Save :size="17"/>保存系统设置</button></div></template><section class="settings-section"><div class="section-heading"><h2>上传日志</h2><button @click="load">刷新日志</button></div><p>最近 30 条记录，仅保留结果、大小、数量和来源；系统最多保存 1000 条。</p><div class="upload-log-list"><article v-for="entry in logs" :key="entry.id"><time>{{new Date(entry.received_at*1000).toLocaleString('zh-CN')}}</time><strong>{{entry.status>=200&&entry.status<300?'成功':'失败'}} · {{entry.status}}</strong><span>{{entry.file_count}} 文件 · {{entry.bytes}} B</span><span>{{entry.device||'来源未识别'}}</span></article><p v-if="!logs.length">暂无上传记录</p></div></section><section class="settings-section"><h2>HTTP 协议调试记录</h2><p>未知原始请求体只保存在服务器，不通过网页公开。可在此查看脱敏方法、类型、表单字段名及长度。</p><details v-for="row in protocol" :key="row.id"><summary>{{row.received_at}} · {{row.method}} · {{row.content_type}} · {{row.files.length}} 文件</summary><pre>{{JSON.stringify(row,null,2)}}</pre></details><p v-if="!protocol.length">暂无调试记录</p></section></div></template>
